/*
 * Rte_Dcm.c
 *
 * [Educational Implementation] hand-written "as if generated by the RTE generator".
 * Real AUTOSAR counterpart: the part of the generated Rte.c that implements the
 * Dcm's client calls, the SchM_Switch_Dcm_* mode switches and Rte_Start.
 *
 * What the RTE does on Rte_Call for a synchronous server call point when
 * client (Dcm) and server (SW-C runnable) are on the same core/partition:
 * it simply invokes the server runnable - often generated as a direct call
 * or even a macro. If they were on different OS-Applications/cores, the RTE
 * would instead use IOC / activate a task and the call could not complete
 * synchronously; DCM_E_PENDING + OpStatus is the mechanism that lets the
 * Dcm keep polling in that case.
 */
#include "Rte.h"
#include "Rte_Dcm.h"
#include "SchM_Dcm.h"
#include "Rte_VehicleInfoSWC.h"
#include "Rte_SecurityAccessSWC.h"
#include "EcuM.h"
#include "UdsTrace.h"

static Dcm_SesCtrlType Rte_ModeDcmDiagnosticSessionControl = DCM_DEFAULT_SESSION;

static const char *Rte_OpName(Dcm_OpStatusType op)
{
    switch (op) {
    case DCM_INITIAL: return "DCM_INITIAL";
    case DCM_PENDING: return "DCM_PENDING";
    case DCM_CANCEL:  return "DCM_CANCEL";
    default:          return "DCM_FORCE_RCRRP_OK";
    }
}

/* ---------------- Rte lifecycle ---------------- */

void Rte_Start(void)
{
    Rte_ModeDcmDiagnosticSessionControl = DCM_DEFAULT_SESSION;
    UDS_TRACE("Rte", "Rte_Start -> init runnables VehicleInfoSWC_Init, SecurityAccessSWC_Init");
    VehicleInfoSWC_Init();
    SecurityAccessSWC_Init();
}

void Rte_Task_10ms(void)
{
    /* OS task body generated by the RTE: runnables mapped to the 10 ms event. */
    VehicleInfoSWC_Run10ms();
}

/* ---------------- DataServices ---------------- */

Std_ReturnType Rte_Call_DataServices_DID_F190_ReadData(Dcm_OpStatusType OpStatus, uint8 *Data)
{
    Std_ReturnType r;
    UDS_TRACE("Rte", "Rte_Call_DataServices_DID_F190_ReadData(%s) -> server runnable VehicleInfoSWC_ReadVin",
              Rte_OpName(OpStatus));
    r = VehicleInfoSWC_ReadVin(OpStatus, Data);
    UDS_TRACE("Rte", "  <- %s", (r == E_OK) ? "E_OK" : ((r == DCM_E_PENDING) ? "DCM_E_PENDING" : "E_NOT_OK"));
    return r;
}

Std_ReturnType Rte_Call_DataServices_DID_F187_ReadData(uint8 *Data)
{
    UDS_TRACE("Rte", "Rte_Call_DataServices_DID_F187_ReadData -> server runnable VehicleInfoSWC_ReadSwVersion");
    return VehicleInfoSWC_ReadSwVersion(Data);
}

