/* ---------------- mode management ---------------- */

void SchM_Switch_Dcm_DcmDiagnosticSessionControl(Dcm_SesCtrlType nextMode)
{
    Rte_ModeDcmDiagnosticSessionControl = nextMode;
    UDS_TRACE("Rte", "SchM_Switch_Dcm_DcmDiagnosticSessionControl(0x%02X): mode users (BswM, SW-Cs) notified",
              (unsigned)nextMode);
}

Dcm_SesCtrlType Rte_Mode_DcmDiagnosticSessionControl_DcmDiagnosticSessionControl(void)
{
    return Rte_ModeDcmDiagnosticSessionControl;
}

void SchM_Switch_Dcm_DcmEcuReset(Rte_ModeType_DcmEcuReset nextMode)
{
    UDS_TRACE("Rte", "SchM_Switch_Dcm_DcmEcuReset(%u)", (unsigned)nextMode);
    if (nextMode == RTE_MODE_DcmEcuReset_EXECUTE) {
        /* Real ECU: BswM is the mode user; a BswM rule triggers an action list
         * (e.g. EcuM_GoDown / Mcu_PerformReset). Here the "BswM role" is inlined. */
        UDS_TRACE("Rte", "  (BswM role) DcmEcuReset=EXECUTE -> EcuM_SimRequestReset");
        EcuM_SimRequestReset();
    }
}
